import{_ as i,o as a,c as e,a2 as t}from"./chunks/framework.BWuWLRhz.js";const c=JSON.parse('{"title":"封裝與發布","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/dev-guide/packaging.md","filePath":"zh-TW/dev-guide/packaging.md","lastUpdated":1785993908000}'),n={name:"zh-TW/dev-guide/packaging.md"};function l(d,s,o,h,p,r){return a(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="封裝與發布" tabindex="-1">封裝與發布 <a class="header-anchor" href="#封裝與發布" aria-label="Permalink to &quot;封裝與發布&quot;">​</a></h1><h2 id="外掛是如何被發現的" tabindex="-1">外掛是如何被發現的 <a class="header-anchor" href="#外掛是如何被發現的" aria-label="Permalink to &quot;外掛是如何被發現的&quot;">​</a></h2><p>App 啟動時會掃描自己的 <code>Plugins/</code> 資料夾(與 <code>Lertaro.App.exe</code> 同層)裡的每一個 <code>.dll</code>，尋找實作了 <code>IPlugin</code> 的型別。沒有單獨的清單檔——組件本身，加上它的型別實作了哪些 SDK 介面，就是完整的契約。</p><h2 id="攜帶外掛自己的相依套件" tabindex="-1">攜帶外掛自己的相依套件 <a class="header-anchor" href="#攜帶外掛自己的相依套件" aria-label="Permalink to &quot;攜帶外掛自己的相依套件&quot;">​</a></h2><p>如果你的外掛需要自己的受控或原生相依 DLL(比如資料庫驅動程式、原生互通程式庫……)，把它們放進 App 的 <code>Plugins/</code> 資料夾下你外掛自己的一個子目錄裡——比如 <code>Plugins/YourPlugin/YourPlugin.dll</code> 連同它的相依套件都放在同一層——而不是平舖在 <code>Plugins/</code> 根目錄下。載入器會遞迴掃描 <code>Plugins/</code>，之後 <code>Assembly.LoadFrom</code> 自帶的同目錄相依探測就會自動解析你的相依套件，不會把它們混進其他外掛的載入目錄裡。</p><p>掃描過程中遇到的非 .NET 檔案(比如原生 DLL <code>e_sqlite3.dll</code>)是預期之內的，會以 <code>Debug</code> 層級記錄，而不是 <code>Error</code>——只有真正載入失敗的受控組件才會記 <code>Error</code>。</p><p>完整的真實範例可以看 <code>BrowserData</code> 外掛的 <code>.csproj</code>:它就是這樣封裝 <code>Microsoft.Data.Sqlite</code> 及其原生相依套件 <code>SQLitePCLRaw</code>/<code>e_sqlite3.dll</code> 的，還帶了 PostBuild/PostPublish 目標，不管是哪種建置方式產生的，都會把它們歸攏進自己的子資料夾。</p><h2 id="開發時自動化複製" tabindex="-1">開發時自動化複製 <a class="header-anchor" href="#開發時自動化複製" aria-label="Permalink to &quot;開發時自動化複製&quot;">​</a></h2><p>Lertaro 自帶的外掛(<code>CoreExtensions</code>、<code>PinyinAlias</code>)都在各自的 <code>.csproj</code> 裡用一個 PostBuild 目標自動化了部署步驟，把剛編譯好的 DLL 直接複製到 App 自己輸出目錄下的 <code>Plugins/</code> 資料夾，這樣重新編譯後下次啟動就能立刻生效:</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Target</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;PostBuild&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> AfterTargets</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;PostBuildEvent&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Copy</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> SourceFiles</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;$(TargetDir)$(TargetName).dll&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">        DestinationFolder</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;..\\..\\App\\bin\\$(Configuration)\\net10.0-windows\\Plugins\\&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">        SkipUnchangedFiles</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;true&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Target</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>把目標路徑改成你自己的建置輸出和 Lertaro App 安裝位置實際所在的路徑即可。</p><h2 id="內嵌語言包" tabindex="-1">內嵌語言包 <a class="header-anchor" href="#內嵌語言包" aria-label="Permalink to &quot;內嵌語言包&quot;">​</a></h2><p>如果外掛實作了 <code>ITranslationProvider</code>(見<a href="./sdk/ui-extensions.html">介面與預覽擴充</a>)，把語言包 JSON 檔案作為內嵌資源封裝，而不是散落的獨立檔案，這樣它們才會跟著 DLL 一起發布:</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ItemGroup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">EmbeddedResource</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Include</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Resources\\Translations\\**\\*.json&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ItemGroup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p><code>TranslationService.LoadEmbeddedTranslations</code>(見<a href="./sdk/services.html">宿主服務</a>)會在執行階段按文化名稱從組件裡把它們讀出來。</p><h2 id="版本號" tabindex="-1">版本號 <a class="header-anchor" href="#版本號" aria-label="Permalink to &quot;版本號&quot;">​</a></h2><p>給外掛的 <code>.csproj</code> 加上 <code>&lt;Version&gt;</code>；它會顯示在<strong>設定 → 外掛</strong>裡對應外掛的卡片上，旁邊還會顯示你的外掛是針對哪個 <code>PluginSdk</code> 版本編譯的——在 SDK 介面發生變化時，這對確認相容性很有用。</p>`,17)])])}const E=i(n,[["render",l]]);export{c as __pageData,E as default};
